create table if not exists public.festival_plan_submissions (id uuid primary key default gen_random_uuid(),proposer_character_id uuid not null references public.characters(id) on delete cascade,owner_type text not null check(owner_type in ('character','club','homeroom')),owner_id uuid,title text not null,description text not null default '',booth_location text,attraction_type text,starts_at timestamptz,ends_at timestamptz,status text not null default 'pending' check(status in ('draft','pending','approved','declined','withdrawn')),reviewer_note text not null default '',reviewed_by uuid,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.festival_plan_submissions enable row level security;create policy festival_submission_self_read on public.festival_plan_submissions for select using(public.current_user_owns_character(proposer_character_id) or public.school_staff_can_manage());create policy festival_submission_self_insert on public.festival_plan_submissions for insert with check(public.current_user_owns_character(proposer_character_id));create policy festival_submission_self_update on public.festival_plan_submissions for update using((public.current_user_owns_character(proposer_character_id) and status in ('draft','pending')) or public.school_staff_can_manage()) with check(public.current_user_owns_character(proposer_character_id) or public.school_staff_can_manage());
create table if not exists public.sports_tournaments (id uuid primary key default gen_random_uuid(),title text not null,sport text not null,season text not null default '2006-2007',format text not null default 'single_elimination' check(format in ('single_elimination','round_robin')),status text not null default 'draft' check(status in ('draft','published','active','completed','cancelled')),starts_at timestamptz,ends_at timestamptz,location text,description text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());create table if not exists public.sports_bracket_matches (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.sports_tournaments(id) on delete cascade,round_number smallint not null default 1,match_number smallint not null,team_a_id uuid references public.sports_teams(id) on delete set null,team_b_id uuid references public.sports_teams(id) on delete set null,team_a_label text,team_b_label text,team_a_score integer,team_b_score integer,winner_team_id uuid references public.sports_teams(id) on delete set null,status text not null default 'scheduled' check(status in ('scheduled','live','final','cancelled')),starts_at timestamptz,location text,note text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tournament_id,round_number,match_number));alter table public.sports_tournaments enable row level security;alter table public.sports_bracket_matches enable row level security;create policy sports_tournaments_read on public.sports_tournaments for select using(status in ('published','active','completed') or public.school_staff_can_manage());create policy sports_tournaments_staff on public.sports_tournaments for all using(public.school_staff_can_manage()) with check(public.school_staff_can_manage());create policy sports_brackets_read on public.sports_bracket_matches for select using(exists(select 1 from public.sports_tournaments t where t.id=tournament_id and t.status in ('published','active','completed')) or public.school_staff_can_manage());create policy sports_brackets_staff on public.sports_bracket_matches for all using(public.school_staff_can_manage()) with check(public.school_staff_can_manage());
